#include "glove_sensor.h"

// PlatformIO project-level header generated by train_movement_model_v2.py.
#include "../../../movement_model_params.h"

#include <Arduino.h>
#include <Wire.h>
#include <math.h>

namespace {

// Hardware pins and sensor configuration from the standalone glove sketch.
constexpr uint8_t MPU_ADDR = 0x68;
constexpr int SDA_PIN = 21;
constexpr int SCL_PIN = 22;
constexpr int FLEX1_PIN = 34;
constexpr int FLEX2_PIN = 35;

constexpr uint8_t PWR_MGMT_1 = 0x6B;
constexpr uint8_t CONFIG = 0x1A;
constexpr uint8_t GYRO_CONFIG = 0x1B;
constexpr uint8_t ACCEL_CONFIG = 0x1C;
constexpr uint8_t ACCEL_XOUT_H = 0x3B;
constexpr uint8_t WHO_AM_I = 0x75;
constexpr uint8_t EXPECTED_WHO_AM_I = 0x70;

constexpr float ACCEL_SCALE = 16384.0f;  // MPU-6500 ±2 g
constexpr float GYRO_SCALE = 131.0f;     // MPU-6500 ±250 deg/s

constexpr float MAHONY_KP = 3.0f;
constexpr float MAHONY_KI = 0.0f;

constexpr uint16_t CALIBRATION_SAMPLES = 1000;
constexpr uint32_t CALIBRATION_SAMPLE_DELAY_MS = 2;
constexpr uint32_t CALIBRATION_SETTLE_MS = 2000;

// gloveUpdate() may be called every loop pass. Limit synchronous I2C reads
// to 1 kHz; all filter dt values are measured from micros().
constexpr uint32_t SENSOR_UPDATE_INTERVAL_US = 1000;
constexpr uint32_t FLEX_UPDATE_INTERVAL_US = 20000;
constexpr uint32_t MAX_SAMPLE_AGE_US = 100000;
constexpr uint16_t I2C_TIMEOUT_MS = 2;

// The trained model uses 1-second, 50 Hz feature windows and the same
// 200 ms inference / vote-confirmation timing as the standalone sketch.
constexpr uint8_t MODEL_WINDOW_SAMPLES = 50;
constexpr uint32_t MODEL_SAMPLE_INTERVAL_US = 20000;
constexpr uint32_t MODEL_UPDATE_INTERVAL_US = 200000;
constexpr uint8_t MODEL_MOVING_CONFIRM_WINDOWS = 2;
constexpr uint8_t MODEL_IDLE_CONFIRM_WINDOWS = 3;

bool initialized = false;
bool sampleValid = false;
uint32_t lastUpdateUs = 0;
uint32_t lastFlexUpdateUs = 0;
uint32_t sampleTimeUs = 0;

float quaternion0 = 1.0f;
float quaternion1 = 0.0f;
float quaternion2 = 0.0f;
float quaternion3 = 0.0f;

float integralFeedbackX = 0.0f;
float integralFeedbackY = 0.0f;
float integralFeedbackZ = 0.0f;

float gyroBiasX = 0.0f;
float gyroBiasY = 0.0f;
float gyroBiasZ = 0.0f;

float latestSample[11] = {0.0f};
float latestFlex1 = 0.0f;
float latestFlex2 = 0.0f;

struct MovementSample {
  float ax, ay, az;
  float gx, gy, gz;
  float flex1, flex2;
};

MovementSample movementBuffer[MODEL_WINDOW_SAMPLES] = {};
uint8_t movementWriteIndex = 0;
uint8_t movementSampleCount = 0;
uint32_t lastMovementSampleUs = 0;
uint32_t lastInferenceUs = 0;
bool movementReady = false;
bool moving = false;
uint8_t movingVotes = 0;
uint8_t idleVotes = 0;
float lastMovementProbability = 0.0f;

struct RawImu {
  int16_t ax;
  int16_t ay;
  int16_t az;
  int16_t gx;
  int16_t gy;
  int16_t gz;
};

bool writeRegister(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(reg);
  Wire.write(value);
  return Wire.endTransmission() == 0;
}

bool readRegister(uint8_t reg, uint8_t &value) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(reg);
  if (Wire.endTransmission(false) != 0) {
    return false;
  }

  const size_t received = Wire.requestFrom(
      static_cast<uint8_t>(MPU_ADDR), static_cast<size_t>(1));
  if (received != 1 || Wire.available() < 1) {
    while (Wire.available()) {
      Wire.read();
    }
    return false;
  }

  value = static_cast<uint8_t>(Wire.read());
  return true;
}

bool readImu(RawImu &raw) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(ACCEL_XOUT_H);
  if (Wire.endTransmission(false) != 0) {
    return false;
  }

  const size_t received = Wire.requestFrom(
      static_cast<uint8_t>(MPU_ADDR), static_cast<size_t>(14));
  if (received != 14 || Wire.available() < 14) {
    while (Wire.available()) {
      Wire.read();
    }
    return false;
  }

  const auto readInt16 = []() -> int16_t {
    const uint16_t high = static_cast<uint8_t>(Wire.read());
    const uint16_t low = static_cast<uint8_t>(Wire.read());
    return static_cast<int16_t>((high << 8) | low);
  };

  raw.ax = readInt16();
  raw.ay = readInt16();
  raw.az = readInt16();
  (void)readInt16();  // Temperature
  raw.gx = readInt16();
  raw.gy = readInt16();
  raw.gz = readInt16();
  return true;
}

bool calibrateGyroscope() {
  // Give the user time to keep the glove still before collecting the bias.
  delay(CALIBRATION_SETTLE_MS);

  int64_t sumX = 0;
  int64_t sumY = 0;
  int64_t sumZ = 0;
  RawImu raw{};

  for (uint16_t i = 0; i < CALIBRATION_SAMPLES; ++i) {
    if (!readImu(raw)) {
      return false;
    }
    sumX += raw.gx;
    sumY += raw.gy;
    sumZ += raw.gz;
    delay(CALIBRATION_SAMPLE_DELAY_MS);
  }

  const float divisor = static_cast<float>(CALIBRATION_SAMPLES) * GYRO_SCALE;
  gyroBiasX = static_cast<float>(sumX) / divisor;
  gyroBiasY = static_cast<float>(sumY) / divisor;
  gyroBiasZ = static_cast<float>(sumZ) / divisor;
  return isfinite(gyroBiasX) && isfinite(gyroBiasY) && isfinite(gyroBiasZ);
}

void mahonyUpdate(float gx, float gy, float gz,
                  float ax, float ay, float az, float dt) {
  constexpr float DEGREES_TO_RADIANS = 0.01745329252f;
  gx *= DEGREES_TO_RADIANS;
  gy *= DEGREES_TO_RADIANS;
  gz *= DEGREES_TO_RADIANS;

  const float accelNorm = sqrtf(ax * ax + ay * ay + az * az);
  if (accelNorm > 0.0f && isfinite(accelNorm)) {
    ax /= accelNorm;
    ay /= accelNorm;
    az /= accelNorm;

    const float halfVx =
        quaternion1 * quaternion3 - quaternion0 * quaternion2;
    const float halfVy =
        quaternion0 * quaternion1 + quaternion2 * quaternion3;
    const float halfVz =
        quaternion0 * quaternion0 - 0.5f + quaternion3 * quaternion3;

    const float halfEx = ay * halfVz - az * halfVy;
    const float halfEy = az * halfVx - ax * halfVz;
    const float halfEz = ax * halfVy - ay * halfVx;

    if (MAHONY_KI > 0.0f) {
      integralFeedbackX += MAHONY_KI * halfEx * dt;
      integralFeedbackY += MAHONY_KI * halfEy * dt;
      integralFeedbackZ += MAHONY_KI * halfEz * dt;
      gx += integralFeedbackX;
      gy += integralFeedbackY;
      gz += integralFeedbackZ;
    } else {
      integralFeedbackX = 0.0f;
      integralFeedbackY = 0.0f;
      integralFeedbackZ = 0.0f;
    }

    gx += MAHONY_KP * halfEx;
    gy += MAHONY_KP * halfEy;
    gz += MAHONY_KP * halfEz;
  }

  const float halfDt = 0.5f * dt;
  gx *= halfDt;
  gy *= halfDt;
  gz *= halfDt;

  const float qa = quaternion0;
  const float qb = quaternion1;
  const float qc = quaternion2;

  quaternion0 += -qb * gx - qc * gy - quaternion3 * gz;
  quaternion1 += qa * gx + qc * gz - quaternion3 * gy;
  quaternion2 += qa * gy - qb * gz + quaternion3 * gx;
  quaternion3 += qa * gz + qb * gy - qc * gx;

  const float normSquared =
      quaternion0 * quaternion0 + quaternion1 * quaternion1 +
      quaternion2 * quaternion2 + quaternion3 * quaternion3;
  if (normSquared > 0.0f && isfinite(normSquared)) {
    const float reciprocalNorm = 1.0f / sqrtf(normSquared);
    quaternion0 *= reciprocalNorm;
    quaternion1 *= reciprocalNorm;
    quaternion2 *= reciprocalNorm;
    quaternion3 *= reciprocalNorm;
  }
}

void getEulerAngles(float &yaw, float &pitch, float &roll) {
  roll = atan2f(
      2.0f * (quaternion0 * quaternion1 + quaternion2 * quaternion3),
      1.0f - 2.0f * (quaternion1 * quaternion1 + quaternion2 * quaternion2));

  const float sinPitch =
      2.0f * (quaternion0 * quaternion2 - quaternion3 * quaternion1);
  if (fabsf(sinPitch) >= 1.0f) {
    pitch = copysignf(PI / 2.0f, sinPitch);
  } else {
    pitch = asinf(sinPitch);
  }

  yaw = atan2f(
      2.0f * (quaternion0 * quaternion3 + quaternion1 * quaternion2),
      1.0f - 2.0f * (quaternion2 * quaternion2 + quaternion3 * quaternion3));

  constexpr float RADIANS_TO_DEGREES = 180.0f / PI;
  yaw *= RADIANS_TO_DEGREES;
  pitch *= RADIANS_TO_DEGREES;
  roll *= RADIANS_TO_DEGREES;
}

void getLinearAcceleration(float ax, float ay, float az,
                           float &linearAx, float &linearAy, float &linearAz) {
  const float gravityX =
      2.0f * (quaternion1 * quaternion3 - quaternion0 * quaternion2);
  const float gravityY =
      2.0f * (quaternion0 * quaternion1 + quaternion2 * quaternion3);
  const float gravityZ =
      2.0f * (quaternion0 * quaternion0 + quaternion3 * quaternion3) - 1.0f;

  linearAx = ax - gravityX;
  linearAy = ay - gravityY;
  linearAz = az - gravityZ;
}

bool finiteSample(const float values[11]) {
  for (uint8_t i = 0; i < 11; ++i) {
    if (!isfinite(values[i])) {
      return false;
    }
  }
  return true;
}

void resetMovementClassifier() {
  movementWriteIndex = 0;
  movementSampleCount = 0;
  lastMovementSampleUs = 0;
  lastInferenceUs = 0;
  movementReady = false;
  moving = false;
  movingVotes = 0;
  idleVotes = 0;
  lastMovementProbability = 0.0f;
}

#if MOVEMENT_MODEL_TRAINED
void calculateMovementFeatures(float features[MOVEMENT_MODEL_FEATURE_COUNT]) {
  float accelMean[3] = {0.0f, 0.0f, 0.0f};
  float accelSquareSum[3] = {0.0f, 0.0f, 0.0f};
  float gyroSquareSum[3] = {0.0f, 0.0f, 0.0f};
  const MovementSample &first = movementBuffer[movementWriteIndex];
  float flexMin[2] = {first.flex1, first.flex2};
  float flexMax[2] = {first.flex1, first.flex2};

  for (uint8_t i = 0; i < MODEL_WINDOW_SAMPLES; ++i) {
    const MovementSample &s =
        movementBuffer[(movementWriteIndex + i) % MODEL_WINDOW_SAMPLES];
    accelMean[0] += s.ax;
    accelMean[1] += s.ay;
    accelMean[2] += s.az;
    gyroSquareSum[0] += s.gx * s.gx;
    gyroSquareSum[1] += s.gy * s.gy;
    gyroSquareSum[2] += s.gz * s.gz;
    if (s.flex1 < flexMin[0]) flexMin[0] = s.flex1;
    if (s.flex1 > flexMax[0]) flexMax[0] = s.flex1;
    if (s.flex2 < flexMin[1]) flexMin[1] = s.flex2;
    if (s.flex2 > flexMax[1]) flexMax[1] = s.flex2;
  }

  for (uint8_t axis = 0; axis < 3; ++axis) {
    accelMean[axis] /= MODEL_WINDOW_SAMPLES;
  }
  for (uint8_t i = 0; i < MODEL_WINDOW_SAMPLES; ++i) {
    const MovementSample &s =
        movementBuffer[(movementWriteIndex + i) % MODEL_WINDOW_SAMPLES];
    const float accel[3] = {s.ax, s.ay, s.az};
    for (uint8_t axis = 0; axis < 3; ++axis) {
      const float difference = accel[axis] - accelMean[axis];
      accelSquareSum[axis] += difference * difference;
    }
  }

  features[0] = sqrtf(accelSquareSum[0] / MODEL_WINDOW_SAMPLES);
  features[1] = sqrtf(accelSquareSum[1] / MODEL_WINDOW_SAMPLES);
  features[2] = sqrtf(accelSquareSum[2] / MODEL_WINDOW_SAMPLES);
  features[3] = sqrtf(gyroSquareSum[0] / MODEL_WINDOW_SAMPLES);
  features[4] = sqrtf(gyroSquareSum[1] / MODEL_WINDOW_SAMPLES);
  features[5] = sqrtf(gyroSquareSum[2] / MODEL_WINDOW_SAMPLES);
  features[6] = flexMax[0] - flexMin[0];
  features[7] = flexMax[1] - flexMin[1];
}

void inferMovement() {
  float features[MOVEMENT_MODEL_FEATURE_COUNT];
  calculateMovementFeatures(features);

  float score = MOVEMENT_LOGISTIC_INTERCEPT;
  for (uint8_t i = 0; i < MOVEMENT_MODEL_FEATURE_COUNT; ++i) {
    float scale = MOVEMENT_FEATURE_SCALE[i];
    if (scale == 0.0f) scale = 1.0f;
    const float standardized =
        (features[i] - MOVEMENT_FEATURE_MEAN[i]) / scale;
    score += MOVEMENT_LOGISTIC_COEFFICIENTS[i] * standardized;
  }

  if (score >= 0.0f) {
    const float exponential = expf(-score);
    lastMovementProbability = 1.0f / (1.0f + exponential);
  } else {
    const float exponential = expf(score);
    lastMovementProbability = exponential / (1.0f + exponential);
  }

  if (lastMovementProbability >= MOVEMENT_PROBABILITY_THRESHOLD) {
    if (movingVotes < MODEL_MOVING_CONFIRM_WINDOWS) ++movingVotes;
    idleVotes = 0;
    if (!moving && movingVotes >= MODEL_MOVING_CONFIRM_WINDOWS) moving = true;
  } else {
    if (idleVotes < MODEL_IDLE_CONFIRM_WINDOWS) ++idleVotes;
    movingVotes = 0;
    if (moving && idleVotes >= MODEL_IDLE_CONFIRM_WINDOWS) moving = false;
  }
  movementReady = true;
}
#endif

void updateMovementClassifier(const float sample[11], uint32_t nowUs) {
#if MOVEMENT_MODEL_TRAINED
  if (lastMovementSampleUs != 0 &&
      static_cast<uint32_t>(nowUs - lastMovementSampleUs) <
          MODEL_SAMPLE_INTERVAL_US) {
    return;
  }
  lastMovementSampleUs = nowUs;

  movementBuffer[movementWriteIndex] = {
      sample[0], sample[1], sample[2],
      sample[3], sample[4], sample[5],
      sample[9], sample[10],
  };
  movementWriteIndex = (movementWriteIndex + 1) % MODEL_WINDOW_SAMPLES;
  if (movementSampleCount < MODEL_WINDOW_SAMPLES) ++movementSampleCount;
  if (movementSampleCount < MODEL_WINDOW_SAMPLES) return;

  if (!movementReady ||
      static_cast<uint32_t>(nowUs - lastInferenceUs) >=
          MODEL_UPDATE_INTERVAL_US) {
    lastInferenceUs = nowUs;
    inferMovement();
  }
#else
  (void)sample;
  (void)nowUs;
#endif
}

}  // namespace

bool gloveBegin() {
  initialized = false;
  sampleValid = false;
  resetMovementClassifier();
  for (float &value : latestSample) {
    value = 0.0f;
  }

  quaternion0 = 1.0f;
  quaternion1 = quaternion2 = quaternion3 = 0.0f;
  integralFeedbackX = integralFeedbackY = integralFeedbackZ = 0.0f;
  gyroBiasX = gyroBiasY = gyroBiasZ = 0.0f;
  latestFlex1 = latestFlex2 = 0.0f;
  lastFlexUpdateUs = 0;

  if (!Wire.begin(SDA_PIN, SCL_PIN)) {
    return false;
  }
  Wire.setClock(400000);
  Wire.setTimeOut(I2C_TIMEOUT_MS);

  uint8_t whoAmI = 0;
  if (!readRegister(WHO_AM_I, whoAmI) || whoAmI != EXPECTED_WHO_AM_I) {
    return false;
  }

  if (!writeRegister(PWR_MGMT_1, 0x01) ||
      !writeRegister(CONFIG, 0x03) ||
      !writeRegister(GYRO_CONFIG, 0x00) ||
      !writeRegister(ACCEL_CONFIG, 0x00)) {
    return false;
  }

  analogReadResolution(12);
  pinMode(FLEX1_PIN, INPUT);
  pinMode(FLEX2_PIN, INPUT);

  // The calibration wait also gives the IMU time to settle after configuration.
  if (!calibrateGyroscope()) {
    return false;
  }

  lastUpdateUs = micros();
  sampleTimeUs = 0;
  initialized = true;
  return true;
}

void gloveUpdate() {
  if (!initialized) {
    return;
  }

  const uint32_t now = micros();
  const uint32_t elapsedUs = now - lastUpdateUs;
  if (elapsedUs < SENSOR_UPDATE_INTERVAL_US) {
    return;
  }
  lastUpdateUs = now;

  const float dt = static_cast<float>(elapsedUs) * 0.000001f;
  if (dt <= 0.0f || dt > 0.1f) {
    sampleValid = false;
    resetMovementClassifier();
    return;
  }

  RawImu raw{};
  if (!readImu(raw)) {
    sampleValid = false;
    resetMovementClassifier();
    return;
  }

  const float ax = static_cast<float>(raw.ax) / ACCEL_SCALE;
  const float ay = static_cast<float>(raw.ay) / ACCEL_SCALE;
  const float az = static_cast<float>(raw.az) / ACCEL_SCALE;

  const float gx = static_cast<float>(raw.gx) / GYRO_SCALE - gyroBiasX;
  const float gy = static_cast<float>(raw.gy) / GYRO_SCALE - gyroBiasY;
  const float gz = static_cast<float>(raw.gz) / GYRO_SCALE - gyroBiasZ;

  mahonyUpdate(gx, gy, gz, ax, ay, az, dt);

  float linearAx = 0.0f;
  float linearAy = 0.0f;
  float linearAz = 0.0f;
  getLinearAcceleration(ax, ay, az, linearAx, linearAy, linearAz);

  float yaw = 0.0f;
  float pitch = 0.0f;
  float roll = 0.0f;
  getEulerAngles(yaw, pitch, roll);

  if (lastFlexUpdateUs == 0 ||
      static_cast<uint32_t>(now - lastFlexUpdateUs) >= FLEX_UPDATE_INTERVAL_US) {
    latestFlex1 = static_cast<float>(analogRead(FLEX1_PIN)) / 4095.0f;
    latestFlex2 = static_cast<float>(analogRead(FLEX2_PIN)) / 4095.0f;
    lastFlexUpdateUs = now;
  }

  const float newSample[11] = {
      linearAx, linearAy, linearAz,
      gx, gy, gz,
      yaw, pitch, roll,
      latestFlex1, latestFlex2,
  };
  if (!finiteSample(newSample)) {
    sampleValid = false;
    resetMovementClassifier();
    return;
  }

  for (uint8_t i = 0; i < 11; ++i) {
    latestSample[i] = newSample[i];
  }
  sampleTimeUs = micros();
  sampleValid = true;
  updateMovementClassifier(newSample, now);
}

bool gloveRead(float out[11]) {
  if (out == nullptr) {
    return false;
  }

  const uint32_t ageUs = micros() - sampleTimeUs;
  if (!initialized || !sampleValid || sampleTimeUs == 0 ||
      ageUs > MAX_SAMPLE_AGE_US || !finiteSample(latestSample)) {
    for (uint8_t i = 0; i < 11; ++i) {
      out[i] = 0.0f;
    }
    return false;
  }

  for (uint8_t i = 0; i < 11; ++i) {
    out[i] = latestSample[i];
  }
  return true;
}

bool gloveIsMoving() {
  return movementReady && moving;
}

bool gloveMovementReady() {
  return movementReady;
}
